[CmdletBinding()]
param(
    [string]$ProjectRoot = "E:\MY PROJECT FOLDER\AURA PROJECT\AURA-Butler-Android-Studio-v0.4.0-Native-Stable",
    [switch]$SkipBuild,
    [switch]$Install
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Section([string]$Text) {
    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host "============================================================" -ForegroundColor Cyan
}

function Get-Sha256([string]$Path) {
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
}

function Write-Bytes([string]$Path, [string]$Base64) {
    $parent = Split-Path -Parent $Path
    if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    [IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Base64))
}

function Find-JavaHome {
    $candidates = New-Object System.Collections.Generic.List[string]
    if ($env:JAVA_HOME) { $candidates.Add($env:JAVA_HOME) }
    foreach ($candidate in @(
        "$env:ProgramFiles\Android\Android Studio\jbr",
        "$env:ProgramFiles\Android Studio\jbr",
        "$env:LOCALAPPDATA\Programs\Android Studio\jbr",
        "$env:LOCALAPPDATA\Google\AndroidStudio\jbr",
        "$env:USERPROFILE\AppData\Local\Programs\Android Studio\jbr"
    )) {
        if ($candidate) { $candidates.Add($candidate) }
    }
    foreach ($candidate in $candidates | Select-Object -Unique) {
        if (Test-Path -LiteralPath (Join-Path $candidate "bin\java.exe") -PathType Leaf) {
            return $candidate
        }
    }
    return $null
}

function Find-Adb {
    foreach ($candidate in @(
        "E:\AndroidSDK\platform-tools\adb.exe",
        "$env:ANDROID_SDK_ROOT\platform-tools\adb.exe",
        "$env:ANDROID_HOME\platform-tools\adb.exe",
        "$env:LOCALAPPDATA\Android\Sdk\platform-tools\adb.exe"
    )) {
        if ($candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            return $candidate
        }
    }
    $cmd = Get-Command adb.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    return $null
}

$ExpectedHashes = @{
    'android\app\build.gradle.kts' = '10CEFD9BE041DEBC2399157A33F8F6A8CA211CC4D6F8D8565AAE3F7CD14F8C59'
    'android\app\src\main\java\in\diganta\aurabutler\background\WakeWordService.kt' = 'E59E7D2832C765586613946696C97019CD7B607F66E61830F7D2D5022E9F6E2F'
    'android\app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt' = '86C4AA6669979C6631D2C3343DC3108E2FBFE9179085EB6BBAC76B11040013D8'
    'android\app\src\main\java\in\diganta\aurabutler\voice\VoiceManager.kt' = '8C538666E6A2AB6CE55C5CFB88CA222923F3838028E62A15E5B1FA257C562357'
    'android\app\src\main\assets\voice\kws\aura_keywords.txt' = '0999CF6AB4C93760A5FE3EBCCC5DA8880A92A4F6BBE89C14E23B2BB3D6692975'
}

$PatchedHashes = @{
    'android\app\build.gradle.kts' = 'C4E8C9D25DF5A43F97F26F62820435E588F199BA123A6D14F2140104FDC3CD73'
    'android\app\src\main\java\in\diganta\aurabutler\background\WakeWordService.kt' = '461E265B2E5565013AE5BCD1957060AD0782C5B26522B80459B5B7E62F7477D6'
    'android\app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt' = '4DB78153AB342DE675F2C124ADF30CE96456F2552BEE63C0DEE4C30ACE41635A'
    'android\app\src\main\java\in\diganta\aurabutler\voice\VoiceManager.kt' = '50E15B43D123FDBC0FFFEF335ED3614D2BC31A1A4F2C9B98404DD7646019FA87'
    'android\app\src\main\assets\voice\kws\aura_keywords.txt' = '312ECBB906CA4EA44790F5753D3C945ED5D8F46EB75FA1E4E0B96E7870135CCE'
}

$Payloads = @{
    'android\app\build.gradle.kts' = ''
    'android\app\src\main\java\in\diganta\aurabutler\background\WakeWordService.kt' = ''
    'android\app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt' = ''
    'android\app\src\main\java\in\diganta\aurabutler\voice\VoiceManager.kt' = ''
    'android\app\src\main\assets\voice\kws\aura_keywords.txt' = ''
}

Section "AURA v0.17.1 Voice Reliability Hotfix"

Write-Host "Project: $ProjectRoot"
Write-Host ""
Write-Host "Repairs:" -ForegroundColor Cyan
Write-Host "  - wake word needing repeated attempts"
Write-Host "  - unsafe broad wake variants / noise false triggers"
Write-Host "  - owner voice accepting poor/noisy samples"
Write-Host "  - owner voice rejecting the real owner because enrollment is weak"
Write-Host ""
Write-Host "Does NOT install Ollama or touch Modal/Qwen/Gemma/News API." -ForegroundColor Green

if (-not (Test-Path -LiteralPath $ProjectRoot -PathType Container)) {
    throw "Project root not found: $ProjectRoot"
}

Section "1/6 Strict v0.17.0 baseline preflight"

foreach ($relative in $ExpectedHashes.Keys) {
    $path = Join-Path $ProjectRoot $relative
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Required baseline file is missing: $relative"
    }
    $actual = Get-Sha256 $path
    $expectedHash = $ExpectedHashes[$relative]
    if ($actual -ne $expectedHash) {
        throw @"
Baseline mismatch. No file was changed.

File: $relative
Expected SHA256: $expectedHash
Actual SHA256:   $actual

This hotfix was generated from your exact uploaded v0.17 source.
Do NOT use -Force or manually bypass this check.
"@
    }
    Write-Host "PASS: $relative" -ForegroundColor Green
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".aura-v0.17.1-backup\$stamp"

Section "2/6 Backup"

foreach ($relative in $ExpectedHashes.Keys) {
    $source = Join-Path $ProjectRoot $relative
    $dest = Join-Path $BackupRoot $relative
    $parent = Split-Path -Parent $dest
    New-Item -ItemType Directory -Path $parent -Force | Out-Null
    Copy-Item -LiteralPath $source -Destination $dest -Force
}
Write-Host "Backup: $BackupRoot" -ForegroundColor Green

$patched = $false
try {
    Section "3/6 Apply deterministic voice patch"

    foreach ($relative in $Payloads.Keys) {
        $path = Join-Path $ProjectRoot $relative
        Write-Bytes -Path $path -Base64 $Payloads[$relative]
        $actual = Get-Sha256 $path
        if ($actual -ne $PatchedHashes[$relative]) {
            throw "Patched hash verification failed: $relative"
        }
        Write-Host "PATCHED: $relative" -ForegroundColor Green
    }
    $patched = $true

    $notesPath = Join-Path $ProjectRoot "AURA-v0.17.1-VOICE-RELIABILITY-NOTES.md"
    [IO.File]::WriteAllText(
        $notesPath,
        @'
# AURA v0.17.1 Voice Reliability Hotfix

This hotfix is based on the exact v0.17.0 source collected on 16 Aug 2026.

## Fixes
- Safer wake-word pronunciation set:
  - removes dangerous broad single-word variants such as `OR A`, `O R A`, and `OUR A`
  - keeps useful Aura / Hey Aura / OK Aura variants
  - retunes the remaining phrases instead of blindly lowering every threshold
- Wake noise control:
  - reduces aggressive amplification of very quiet room noise
  - requires recent real acoustic energy before accepting a KWS trigger
- Owner voice reliability:
  - profile schema v2: old weak enrollment must be registered again
  - 5 enrollment samples instead of 3
  - minimum owner sample length increased
  - noise-floor / voiced-duration / clipping quality gate
  - trims excess silence before speaker embedding
  - normalizes speaker sample level
  - enrollment consistency requirement raised
  - effective owner threshold cannot fall below 0.60
  - clearer rejection reason shown in UI/notification
- Version:
  - versionCode 26
  - versionName 0.17.1-voice-reliability

## Important
After installing the APK as an UPDATE:
1. Open AURA Settings.
2. Register Owner Voice again. The old v0.16/v0.17 voice profile is intentionally not trusted.
3. Enroll in a quiet room at normal phone distance.
4. For daily use, "Hey Aura" should be the most robust phrase in noisy rooms.
5. Sensitive actions must still keep AURA's normal confirmation layer.

This hotfix does NOT:
- install or require Ollama
- deploy or change Modal
- change Qwen/Gemma
- change News API
- change Whisper/Piper
- upgrade Sherpa-ONNX from v1.13.4 (that belongs in the controlled v0.18 voice-runtime test)

'@,
        (New-Object Text.UTF8Encoding($false))
    )

    Section "4/6 Static integrity audit"

    $gradlePath = Join-Path $ProjectRoot "android\app\build.gradle.kts"
    $wakePath = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\background\WakeWordService.kt"
    $ownerPath = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\OwnerVoiceGuard.kt"
    $keywordsPath = Join-Path $ProjectRoot "android\app\src\main\assets\voice\kws\aura_keywords.txt"

    $gradleText = [IO.File]::ReadAllText($gradlePath)
    $wakeText = [IO.File]::ReadAllText($wakePath)
    $ownerText = [IO.File]::ReadAllText($ownerPath)
    $keywordsText = [IO.File]::ReadAllText($keywordsPath)

    $checks = @(
        @("version 0.17.1", $gradleText.Contains('versionName = "0.17.1-voice-reliability"')),
        @("versionCode 26", $gradleText.Contains("versionCode = 26")),
        @("owner profile schema v2", $ownerText.Contains("PROFILE_SCHEMA_VERSION = 2")),
        @("5-sample enrollment", $ownerText.Contains("ENROLLMENT_SAMPLES = 5")),
        @("owner quality gate", $ownerText.Contains("prepareSpeakerSample")),
        @("owner threshold floor 0.60", $ownerText.Contains("DEFAULT_THRESHOLD = 0.60f")),
        @("wake speech-evidence gate", $wakeText.Contains("WAKE_SPEECH_EVIDENCE_MS")),
        @("safer wake gain", $wakeText.Contains("rms < 0.0020f -> 1.25f")),
        @("dangerous OR-A single wake removed", -not $keywordsText.Contains("▁OR A")),
        @("Hey Aura retained", $keywordsText.Contains("@HEY_AURA")),
        @("OK Aura retained", $keywordsText.Contains("@OK_AURA"))
    )

    foreach ($check in $checks) {
        if (-not [bool]$check[1]) {
            throw "Static integrity check failed: $($check[0])"
        }
        Write-Host "PASS: $($check[0])" -ForegroundColor Green
    }

    if (-not $SkipBuild) {
        Section "5/6 Android verification"

        $androidRoot = Join-Path $ProjectRoot "android"
        $gradlew = Join-Path $androidRoot "gradlew.bat"
        if (-not (Test-Path -LiteralPath $gradlew -PathType Leaf)) {
            throw "gradlew.bat not found: $gradlew"
        }

        $javaHome = Find-JavaHome
        if ($javaHome) {
            $env:JAVA_HOME = $javaHome
            $env:PATH = (Join-Path $javaHome "bin") + ";" + $env:PATH
            Write-Host "JAVA_HOME: $javaHome"
        } else {
            Write-Host "WARN: Android Studio JBR/JAVA_HOME was not auto-detected; Gradle will use the current Java environment." -ForegroundColor Yellow
        }

        Push-Location $androidRoot
        try {
            & $gradlew --no-daemon testDebugUnitTest lintDebug assembleDebug
            if ($LASTEXITCODE -ne 0) {
                throw "Gradle verification failed with exit code $LASTEXITCODE."
            }
        } finally {
            Pop-Location
        }

        $builtApk = Join-Path $androidRoot "app\build\outputs\apk\debug\app-debug.apk"
        if (-not (Test-Path -LiteralPath $builtApk -PathType Leaf)) {
            throw "Gradle reported success but the expected debug APK was not found."
        }

        $finalApk = Join-Path $ProjectRoot "AURA-v0.17.1-voice-reliability-debug.apk"
        Copy-Item -LiteralPath $builtApk -Destination $finalApk -Force
        Write-Host "PASS: JVM tests + lintDebug + assembleDebug" -ForegroundColor Green
        Write-Host "APK: $finalApk" -ForegroundColor Green

        if ($Install) {
            Section "6/6 Install as UPDATE"
            $adb = Find-Adb
            if (-not $adb) {
                throw "Install was requested but adb.exe was not found."
            }
            & $adb start-server | Out-Host
            & $adb install -r $finalApk | Out-Host
            if ($LASTEXITCODE -ne 0) {
                throw "ADB update install failed with exit code $LASTEXITCODE."
            }
            Write-Host "PASS: APK installed with -r; existing AURA app data was preserved." -ForegroundColor Green
        } else {
            Section "6/6 Ready"
            Write-Host "Build is verified. Install the APK as an UPDATE with adb install -r." -ForegroundColor Green
        }
    } else {
        Section "5/6 Build skipped"
        Write-Host "Source was patched but not compiled because -SkipBuild was supplied." -ForegroundColor Yellow
        Section "6/6 Ready"
    }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host "SUCCESS: AURA v0.17.1 voice reliability hotfix applied." -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "IMPORTANT AFTER INSTALL:" -ForegroundColor Yellow
    Write-Host "  1. Open AURA > Settings."
    Write-Host "  2. Register Owner Voice AGAIN. Old profile schema is intentionally rejected."
    Write-Host "  3. Enroll all 5 samples in a quiet room at normal phone distance."
    Write-Host "  4. Test yourself, another person, TV/music, and room noise."
    Write-Host "  5. In noisy places prefer 'Hey Aura' or 'OK Aura' for the most distinctive wake phrase."
    Write-Host ""
    Write-Host "Backup: $BackupRoot"
}
catch {
    Write-Host ""
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red

    if ($patched -and (Test-Path -LiteralPath $BackupRoot -PathType Container)) {
        Write-Host "Restoring the original v0.17 files..." -ForegroundColor Yellow
        foreach ($relative in $ExpectedHashes.Keys) {
            $backup = Join-Path $BackupRoot $relative
            $target = Join-Path $ProjectRoot $relative
            if (Test-Path -LiteralPath $backup -PathType Leaf) {
                Copy-Item -LiteralPath $backup -Destination $target -Force
            }
        }
        Write-Host "RESTORED: original voice source." -ForegroundColor Green
    }
    throw
}
